CREATE OR REPLACE FUNCTION public.jcm_process_scoring_event_core(p_match_id uuid, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb, p_client_event_id uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m record;i record;st record;rs record;prev jsonb;result jsonb;v_seq bigint;v_striker uuid;v_non uuid;v_bowler uuid;v_batter uuid;v_fielder uuid;v_event_striker uuid;v_event_non uuid;v_runs integer:=0;v_legal boolean:=true;v_delivery boolean:=true;v_dismissal text;v_completed integer:=0;v_over_complete boolean:=false;v_pair_id uuid;v_pair_no integer;v_batting_team uuid;v_fielding_team uuid;v_total_balls integer;v_new_batter uuid;v_replace uuid;v_base_extra text;v_outcome_type text;
begin
 if auth.uid() is null then raise exception 'Authentication required.';end if;if not public.jcm_can_score_match(p_match_id) then raise exception 'Scoring access denied for this match.';end if;select * into m from public.jcm_matches where id=p_match_id for update;if not found then raise exception 'Match not found.';end if;
 if p_event_type not in('START_INNINGS','SET_BOWLER','SET_PAIR','TARGET_DECISION','STRIKER_SWITCH','RUN','WIDE','NO_BALL','WICKET','RUN_OUT','COACH_THROW','RETIREMENT','OVER_COMPLETE','PAIR_COMPLETE','INNINGS_COMPLETE','CORRECTION','REPLACE_BATTER') then raise exception 'Unsupported scoring event: %',p_event_type;end if;if exists(select 1 from public.jcm_scoring_events where client_event_id=p_client_event_id) then select to_jsonb(s) into result from public.jcm_match_state s where s.match_id=p_match_id;return jsonb_build_object('ok',true,'duplicate',true,'state',result);end if;select * into st from public.jcm_match_state where match_id=p_match_id for update;if not found then raise exception 'Match state not initialized.';end if;if p_payload ? 'expected_state_version' and (p_payload->>'expected_state_version')::bigint<>st.state_version then raise exception 'State changed on another device. Please reload the match.';end if;prev:=public.jcm_scoring_snapshot(p_match_id);select * into i from public.jcm_innings where id=st.innings_id for update;select legal_balls_per_over,innings_max_balls,pair_max_balls,batter_max_balls,batter_retire_runs,batter_retire_balls,coach_throw_enabled,equal_batting_opportunity,wides_count_as_ball,no_balls_count_as_ball into rs from public.jcm_rule_sets where code=m.ruleset and active;if not found then raise exception 'Ruleset % is not active.',m.ruleset;end if;
 if p_event_type='START_INNINGS' then v_batting_team:=(p_payload->>'batting_team_id')::uuid;v_fielding_team:=(p_payload->>'fielding_team_id')::uuid;v_striker:=nullif(p_payload->>'striker_id','')::uuid;v_non:=nullif(p_payload->>'non_striker_id','')::uuid;v_bowler:=nullif(p_payload->>'bowler_id','')::uuid;if v_batting_team is null or v_fielding_team is null or v_striker is null or v_non is null or v_bowler is null or v_striker=v_non then raise exception 'Batting team, fielding team, two different batters and bowler are required.';end if;if not exists(select 1 from public.jcm_match_players where match_id=p_match_id and team_id=v_batting_team and player_id in(v_striker,v_non) and selected) then raise exception 'Both batters must be selected players.';end if;if not exists(select 1 from public.jcm_match_players where match_id=p_match_id and team_id=v_fielding_team and player_id=v_bowler and selected) then raise exception 'Bowler must be a selected player.';end if;if i.id is null then select * into i from public.jcm_innings where match_id=p_match_id and innings_no=1;if i.id is null then insert into public.jcm_innings(match_id,innings_no,batting_team_id,fielding_team_id,target,started_at) values(p_match_id,1,v_batting_team,v_fielding_team,null,now()) returning * into i;end if;else update public.jcm_innings set batting_team_id=v_batting_team,fielding_team_id=v_fielding_team,started_at=coalesce(started_at,now()),completed=false,completed_at=null where id=i.id;select * into i from public.jcm_innings where id=i.id;end if;update public.jcm_matches set status='LIVE',scorer_user_id=coalesce(scorer_user_id,auth.uid()),updated_at=now() where id=p_match_id;if rs.equal_batting_opportunity then select id into v_pair_id from public.jcm_batting_pairs where innings_id=i.id and pair_no=1;if v_pair_id is null then insert into public.jcm_batting_pairs(innings_id,pair_no,batter_a_id,batter_b_id) values(i.id,1,v_striker,v_non) returning id into v_pair_id;end if;end if;update public.jcm_match_state set innings_id=i.id,striker_id=v_striker,non_striker_id=v_non,current_bowler_id=v_bowler,batting_pair_id=v_pair_id,over_no=1,over_ball_count=0,pair_ball_count=0,batter_ball_count=0,pending_workflow=null,workflow_state=jsonb_build_object('started',true),state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;
 elsif p_event_type='SET_BOWLER' then v_bowler:=nullif(p_payload->>'bowler_id','')::uuid;if v_bowler is null then raise exception 'Bowler is required.';end if;if not exists(select 1 from public.jcm_match_players where match_id=p_match_id and team_id=i.fielding_team_id and player_id=v_bowler and selected) then raise exception 'Bowler must be a selected player.';end if;insert into public.jcm_over_assignments(innings_id,over_no,bowler_id,repeat_over) values(i.id,st.over_no,v_bowler,coalesce((p_payload->>'repeat_over')::boolean,false)) on conflict(innings_id,over_no) do update set bowler_id=excluded.bowler_id,repeat_over=excluded.repeat_over;update public.jcm_match_state set current_bowler_id=v_bowler,pending_workflow=null,state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;
 elsif p_event_type='SET_PAIR' then if not rs.equal_batting_opportunity then raise exception 'Pairs are not used by this ruleset.';end if;v_striker:=nullif(p_payload->>'striker_id','')::uuid;v_non:=nullif(p_payload->>'non_striker_id','')::uuid;if v_striker is null or v_non is null or v_striker=v_non then raise exception 'Two different batters are required.';end if;if not exists(select 1 from public.jcm_match_players where match_id=p_match_id and team_id=i.batting_team_id and player_id in(v_striker,v_non) and selected) then raise exception 'Both batters must be selected players.';end if;v_pair_no:=coalesce((select max(pair_no)+1 from public.jcm_batting_pairs where innings_id=i.id),1);insert into public.jcm_batting_pairs(innings_id,pair_no,batter_a_id,batter_b_id) values(i.id,v_pair_no,v_striker,v_non) returning id into v_pair_id;update public.jcm_match_state set striker_id=v_striker,non_striker_id=v_non,batting_pair_id=v_pair_id,pair_ball_count=0,batter_ball_count=0,pending_workflow=case when st.current_bowler_id is null then 'BOWLER_REQUIRED' else null end,state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;
 elsif p_event_type='REPLACE_BATTER' then v_new_batter:=nullif(p_payload->>'new_batter_id','')::uuid;v_replace:=nullif(p_payload->>'replaces_player_id','')::uuid;if v_new_batter is null or v_replace is null then raise exception 'New batter and replaced player are required.';end if;if not exists(select 1 from public.jcm_match_players where match_id=p_match_id and team_id=i.batting_team_id and player_id=v_new_batter and selected) then raise exception 'New batter must be a selected player.';end if;if v_replace<>st.striker_id and v_replace<>st.non_striker_id then raise exception 'The replaced player is not one of the active batters.';end if;if v_new_batter=st.striker_id or v_new_batter=st.non_striker_id then raise exception 'New batter is already active.';end if;if v_replace=st.striker_id then v_striker:=v_new_batter;v_non:=st.non_striker_id;else v_striker:=st.striker_id;v_non:=v_new_batter;end if;update public.jcm_match_state set striker_id=v_striker,non_striker_id=v_non,pending_workflow=null,workflow_state='{}'::jsonb,state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;
 elsif p_event_type='STRIKER_SWITCH' then if st.striker_id is null or st.non_striker_id is null then raise exception 'Two active batters are required before switching strike.';end if;update public.jcm_match_state set striker_id=st.non_striker_id,non_striker_id=st.striker_id,state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;
 elsif p_event_type in('RUN','WIDE','NO_BALL','WICKET','RUN_OUT','COACH_THROW','RETIREMENT') then
  if st.striker_id is null or st.non_striker_id is null then raise exception 'Two active batters are required.';end if;if st.current_bowler_id is null then raise exception 'A current bowler must be assigned.';end if;v_striker:=st.striker_id;v_non:=st.non_striker_id;v_event_striker:=v_striker;v_event_non:=v_non;v_bowler:=st.current_bowler_id;v_runs:=greatest(coalesce((p_payload->>'runs')::integer,0),0);
  if p_event_type='RUN' then if v_runs>6 then raise exception 'Runs must be between 0 and 6.';end if;v_legal:=true;elsif p_event_type='WIDE' then v_runs:=greatest(coalesce((p_payload->>'wide_runs')::integer,1),1)+greatest(coalesce((p_payload->>'completed_runs')::integer,0),0);v_completed:=greatest(coalesce((p_payload->>'completed_runs')::integer,0),0);v_legal:=rs.wides_count_as_ball;elsif p_event_type='NO_BALL' then v_runs:=greatest(coalesce((p_payload->>'no_ball_runs')::integer,1),1)+greatest(coalesce((p_payload->>'completed_runs')::integer,0),0);v_completed:=greatest(coalesce((p_payload->>'completed_runs')::integer,0),0);v_legal:=rs.no_balls_count_as_ball;elsif p_event_type='COACH_THROW' then if not rs.coach_throw_enabled then raise exception 'Coach Throw is not enabled for this ruleset.';end if;v_base_extra:=upper(coalesce(p_payload->>'base_extra',''));v_outcome_type:=upper(coalesce(p_payload->>'outcome_type','RUN'));if v_base_extra not in('WIDE','NO_BALL') then raise exception 'Coach Throw must follow a wide or no-ball.';end if;if v_outcome_type not in('RUN','WICKET') then raise exception 'Coach Throw outcome must be RUN or WICKET.';end if;if coalesce((st.workflow_state->>'coach_throw_pending')::boolean,false) is not true or upper(coalesce(st.workflow_state->>'coach_throw_base',''))<>v_base_extra then raise exception 'Coach Throw is only allowed immediately after the pending %.',v_base_extra;end if;v_runs:=greatest(coalesce((p_payload->>'runs')::integer,0),0);if v_runs>6 then raise exception 'Coach Throw runs must be between 0 and 6.';end if;v_legal:=true;if v_outcome_type='WICKET' then v_batter:=coalesce(nullif(p_payload->>'dismissed_player_id','')::uuid,st.striker_id);v_fielder:=nullif(p_payload->>'fielder_id','')::uuid;v_dismissal:=coalesce(nullif(p_payload->>'dismissal_type',''),'BOWLED');if m.ruleset='U6' and v_dismissal not in('BOWLED','CAUGHT','RUN_OUT','HIT_WICKET') then raise exception 'Invalid O/6 dismissal type.';end if;if m.ruleset<>'U6' and v_dismissal not in('BOWLED','CAUGHT','STUMPED','LBW','HIT_WICKET','OBSTRUCTING_THE_FIELD','RUN_OUT') then raise exception 'Invalid dismissal type.';end if;end if;elsif p_event_type='RETIREMENT' then v_batter:=coalesce(nullif(p_payload->>'player_id','')::uuid,st.striker_id);update public.jcm_player_match_stats set retired=true where match_id=p_match_id and innings_no=i.innings_no and player_id=v_batter;update public.jcm_match_state set pending_workflow='BATTER_REPLACEMENT',workflow_state=jsonb_build_object('retired_player_id',v_batter),state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;elsif p_event_type in('WICKET','RUN_OUT') then v_batter:=coalesce(nullif(p_payload->>'dismissed_player_id','')::uuid,st.striker_id);v_fielder:=nullif(p_payload->>'fielder_id','')::uuid;v_dismissal:=coalesce(nullif(p_payload->>'dismissal_type',''),case when p_event_type='RUN_OUT' then 'RUN_OUT' else null end);if v_dismissal is null then raise exception 'Dismissal type is required.';end if;if p_event_type='WICKET' and v_dismissal not in('BOWLED','CAUGHT','STUMPED','LBW','HIT_WICKET','OBSTRUCTING_THE_FIELD') then raise exception 'Invalid dismissal type.';end if;if p_event_type='RUN_OUT' and v_dismissal<>'RUN_OUT' then raise exception 'Run out event must use RUN_OUT dismissal.';end if;v_legal:=coalesce((p_payload->>'legal_ball')::boolean,true);v_delivery:=coalesce((p_payload->>'counts_as_delivery')::boolean,true);end if;
  if p_event_type<>'RETIREMENT' then insert into public.jcm_player_match_stats(match_id,innings_no,player_id,team_id) values(p_match_id,i.innings_no,v_striker,i.batting_team_id) on conflict do nothing;insert into public.jcm_player_match_stats(match_id,innings_no,player_id,team_id) values(p_match_id,i.innings_no,v_bowler,i.fielding_team_id) on conflict do nothing;if p_event_type='RUN' then update public.jcm_player_match_stats set runs=runs+v_runs,balls=balls+1,fours=fours+case when v_runs=4 then 1 else 0 end,sixes=sixes+case when v_runs=6 then 1 else 0 end where match_id=p_match_id and innings_no=i.innings_no and player_id=v_striker;elsif p_event_type='NO_BALL' and v_completed>0 then update public.jcm_player_match_stats set runs=runs+v_completed,balls=balls+case when v_legal then 1 else 0 end where match_id=p_match_id and innings_no=i.innings_no and player_id=v_striker;elsif p_event_type in('WICKET','RUN_OUT') then update public.jcm_player_match_stats set runs=runs+v_runs,balls=balls+case when v_legal then 1 else 0 end where match_id=p_match_id and innings_no=i.innings_no and player_id=v_striker;elsif p_event_type='COACH_THROW' and v_outcome_type='RUN' and v_base_extra='NO_BALL' then update public.jcm_player_match_stats set runs=runs+v_runs,fours=fours+case when v_runs=4 then 1 else 0 end,sixes=sixes+case when v_runs=6 then 1 else 0 end where match_id=p_match_id and innings_no=i.innings_no and player_id=v_striker;end if;if p_event_type='WIDE' then update public.jcm_player_match_stats set wides=wides+1 where match_id=p_match_id and innings_no=i.innings_no and player_id=v_bowler;end if;if p_event_type='NO_BALL' then update public.jcm_player_match_stats set no_balls=no_balls+1 where match_id=p_match_id and innings_no=i.innings_no and player_id=v_bowler;end if;if p_event_type in('RUN','WIDE','NO_BALL','WICKET','RUN_OUT','COACH_THROW') then update public.jcm_player_match_stats set balls=balls+case when v_legal then 1 else 0 end,runs=runs+case when p_event_type='COACH_THROW' then 0 else v_runs end where match_id=p_match_id and innings_no=i.innings_no and player_id=v_bowler;end if;if p_event_type in('WIDE','NO_BALL') then update public.jcm_player_match_stats set unplayable_balls=unplayable_balls+1 where match_id=p_match_id and innings_no=i.innings_no and player_id in(v_striker,v_bowler);end if;if p_event_type='COACH_THROW' then update public.jcm_player_match_stats set balls=balls+1,coach_runs=coach_runs+case when v_base_extra='NO_BALL' and v_outcome_type='RUN' then v_runs else 0 end where match_id=p_match_id and innings_no=i.innings_no and player_id=v_striker;end if;if p_event_type in('WICKET','RUN_OUT') or (p_event_type='COACH_THROW' and v_outcome_type='WICKET') then update public.jcm_player_match_stats set wickets=wickets+1,dismissal_type=v_dismissal where match_id=p_match_id and innings_no=i.innings_no and player_id=v_batter;if v_fielder is not null and v_dismissal='CAUGHT' then update public.jcm_player_match_stats set catches=catches+1 where match_id=p_match_id and innings_no=i.innings_no and player_id=v_fielder;end if;if v_fielder is not null and v_dismissal='RUN_OUT' then update public.jcm_player_match_stats set run_outs=run_outs+1 where match_id=p_match_id and innings_no=i.innings_no and player_id=v_fielder;end if;if v_fielder is not null and v_dismissal='STUMPED' then update public.jcm_player_match_stats set stumpings=stumpings+1 where match_id=p_match_id and innings_no=i.innings_no and player_id=v_fielder;end if;end if;
   update public.jcm_innings set runs=runs+v_runs,wickets=wickets+case when p_event_type in('WICKET','RUN_OUT') or (p_event_type='COACH_THROW' and v_outcome_type='WICKET') then 1 else 0 end,total_balls=total_balls+case when v_delivery then 1 else 0 end,legal_balls=legal_balls+case when v_legal and v_delivery then 1 else 0 end where id=i.id;if rs.equal_batting_opportunity and v_legal and v_delivery and st.batting_pair_id is not null then update public.jcm_batting_pairs set pair_balls=pair_balls+1 where id=st.batting_pair_id;end if;select total_balls into v_total_balls from public.jcm_innings where id=i.id;if rs.innings_max_balls is not null and v_total_balls>=rs.innings_max_balls then update public.jcm_match_state set pending_workflow='INNINGS_COMPLETE',workflow_state=jsonb_build_object('reason','BALL_LIMIT') where match_id=p_match_id;end if;if i.innings_no=2 and i.target is not null and(select runs from public.jcm_innings where id=i.id)>=i.target then update public.jcm_match_state set pending_workflow='TARGET_REACHED',workflow_state=jsonb_build_object('target',i.target,'score',(select runs from public.jcm_innings where id=i.id),'runs_over',(select runs from public.jcm_innings where id=i.id)-i.target) where match_id=p_match_id;end if;if rs.equal_batting_opportunity and st.batting_pair_id is not null and p_event_type in('RUN','WICKET','COACH_THROW') and(select pair_balls from public.jcm_batting_pairs where id=st.batting_pair_id)>=rs.pair_max_balls then update public.jcm_batting_pairs set completed=true where id=st.batting_pair_id;update public.jcm_match_state set pending_workflow='PAIR_REQUIRED' where match_id=p_match_id;end if;
   v_over_complete:=v_delivery and v_legal and(st.over_ball_count+1)>=rs.legal_balls_per_over;if v_over_complete then if v_runs%2=1 then v_striker:=st.striker_id;v_non:=st.non_striker_id;else v_striker:=st.non_striker_id;v_non:=st.striker_id;end if;update public.jcm_match_state set striker_id=v_striker,non_striker_id=v_non,over_no=over_no+1,over_ball_count=0,current_bowler_id=null,pending_workflow=case when pending_workflow='PAIR_REQUIRED' then 'PAIR_REQUIRED' else 'BOWLER_REQUIRED' end,workflow_state='{}'::jsonb,state_version=state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;else if p_event_type='COACH_THROW' and mod(v_runs,2)=1 then v_striker:=st.non_striker_id;v_non:=st.striker_id;elsif p_event_type not in('WIDE','NO_BALL','COACH_THROW') and v_delivery and mod(v_runs,2)=1 then v_striker:=st.non_striker_id;v_non:=st.striker_id;end if;update public.jcm_match_state set striker_id=v_striker,non_striker_id=v_non,over_ball_count=over_ball_count+case when v_legal and v_delivery then 1 else 0 end,pair_ball_count=case when rs.equal_batting_opportunity and st.batting_pair_id is not null then coalesce((select bp.pair_balls from public.jcm_batting_pairs bp where bp.id=st.batting_pair_id),st.pair_ball_count) else st.pair_ball_count end,pending_workflow=case when (p_event_type in('WICKET','RUN_OUT') or (p_event_type='COACH_THROW' and v_outcome_type='WICKET')) and m.ruleset not in('U6','U7') then 'BATTER_REPLACEMENT' when pending_workflow is not null then pending_workflow else null end,workflow_state=case when (p_event_type in('WICKET','RUN_OUT') or (p_event_type='COACH_THROW' and v_outcome_type='WICKET')) and m.ruleset not in('U6','U7') then jsonb_build_object('dismissed_player_id',v_batter,'dismissal_type',v_dismissal,'fielder_id',v_fielder) when p_event_type in('WIDE','NO_BALL') then jsonb_build_object('coach_throw_pending',true,'coach_throw_base',p_event_type) when p_event_type='COACH_THROW' then '{}'::jsonb else workflow_state end,state_version=state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;end if;
  end if;
 elsif p_event_type='PAIR_COMPLETE' then update public.jcm_batting_pairs set completed=true where id=st.batting_pair_id;update public.jcm_match_state set pending_workflow='PAIR_REQUIRED',state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;
 elsif p_event_type='OVER_COMPLETE' then update public.jcm_match_state set pending_workflow='BOWLER_REQUIRED',current_bowler_id=null,over_ball_count=0,over_no=over_no+1,state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;
 elsif p_event_type='INNINGS_COMPLETE' then update public.jcm_innings set completed=true,completed_at=now() where id=i.id;if i.innings_no=1 then insert into public.jcm_innings(match_id,innings_no,batting_team_id,fielding_team_id,target) values(p_match_id,2,i.fielding_team_id,i.batting_team_id,i.runs+1) on conflict do nothing;update public.jcm_match_state set innings_id=(select id from public.jcm_innings where match_id=p_match_id and innings_no=2),striker_id=null,non_striker_id=null,current_bowler_id=null,batting_pair_id=null,over_no=1,over_ball_count=0,pair_ball_count=0,batter_ball_count=0,pending_workflow='INNINGS_2_SETUP',workflow_state=jsonb_build_object('target',i.runs+1),state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;else update public.jcm_matches set status='COMPLETED',completed_at=now(),result_reason='INNINGS_COMPLETE',updated_at=now() where id=p_match_id;update public.jcm_match_state set pending_workflow='MATCH_COMPLETE',state_version=st.state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;end if;
 elsif p_event_type='TARGET_DECISION' then if(p_payload->>'action') not in('END_MATCH','PLAY_ON') then raise exception 'Target decision must be END_MATCH or PLAY_ON.';end if;if(p_payload->>'action')='END_MATCH' then update public.jcm_matches set status='COMPLETED',completed_at=now(),result_reason='TARGET_REACHED',result_winner_team_id=i.batting_team_id,updated_at=now() where id=p_match_id;update public.jcm_match_state set pending_workflow='MATCH_COMPLETE',state_version=state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;else update public.jcm_match_state set pending_workflow=null,workflow_state=jsonb_build_object('play_on',true,'target',i.target),state_version=state_version+1,updated_by=auth.uid(),updated_at=now() where match_id=p_match_id;end if;end if;
 select * into st from public.jcm_match_state where match_id=p_match_id;select * into i from public.jcm_innings where id=st.innings_id;select coalesce(max(sequence_number),0)+1 into v_seq from public.jcm_scoring_events where match_id=p_match_id;insert into public.jcm_scoring_events(match_id,innings_id,sequence_number,event_type,striker_id,non_striker_id,bowler_id,runs,extras,wicket,dismissal_type,fielder_id,previous_state,resulting_state,client_event_id,created_by) values(p_match_id,i.id,v_seq,p_event_type,case when p_event_type in('RUN','WIDE','NO_BALL','WICKET','RUN_OUT','COACH_THROW','RETIREMENT') then v_event_striker else st.striker_id end,case when p_event_type in('RUN','WIDE','NO_BALL','WICKET','RUN_OUT','COACH_THROW','RETIREMENT') then v_event_non else st.non_striker_id end,case when p_event_type in('RUN','WIDE','NO_BALL','WICKET','RUN_OUT','COACH_THROW','RETIREMENT') then v_bowler else st.current_bowler_id end,v_runs,case when p_event_type='WIDE' then jsonb_build_object('type','WIDE','wide_runs',coalesce((p_payload->>'wide_runs')::integer,1),'completed_runs',coalesce((p_payload->>'completed_runs')::integer,0)) when p_event_type='NO_BALL' then jsonb_build_object('type','NO_BALL','no_ball_runs',coalesce((p_payload->>'no_ball_runs')::integer,1),'completed_runs',coalesce((p_payload->>'completed_runs')::integer,0)) when p_event_type='COACH_THROW' then jsonb_build_object('type','COACH_THROW','base_extra',v_base_extra,'outcome_type',v_outcome_type,'runs',v_runs,'unplayable',coalesce((p_payload->>'unplayable')::boolean,false)) else '{}'::jsonb end,case when p_event_type in('WICKET','RUN_OUT') or (p_event_type='COACH_THROW' and v_outcome_type='WICKET') then jsonb_build_object('dismissed_player_id',v_batter) else null end,v_dismissal,v_fielder,prev,to_jsonb(st),p_client_event_id,auth.uid());perform public.jcm_rebuild_player_match_stats(p_match_id);return jsonb_build_object('ok',true,'duplicate',false,'state',to_jsonb(st),'innings',to_jsonb(i));
end; $function$

